def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if n == 0:
        return 0
    # Seed from the float approximation when the number is small enough to be
    # represented as a float; otherwise seed from the bit length. Float sqrt
    # is not exact, so either way the result is corrected with integer math.
    if n < (1 << 1024):
        r = int(n ** 0.5)
    else:
        r = 1 << ((n.bit_length() + 1) // 2 - 1)
    while r * r > n:
        r -= 1
    while (r + 1) * (r + 1) <= n:
        r += 1
    return r

def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if n == 0:
        return 0
    # Seed: float approximation when the number is representable as a float,
    # otherwise from the bit length (a power of two just above sqrt(n)).
    if n < (1 << 1024):
        r = int(n ** 0.5)
    else:
        r = 1 << (n.bit_length() + 1) // 2
    # Correct with integer arithmetic only: r may overshoot or undershoot
    # the seed, so walk to the floor of the true square root.
    while r * r > n:
        r -= 1
    while (r + 1) * (r + 1) <= n:
        r += 1
    return r

def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if n == 0:
        return 0
    # Seed the correction loop: a float approximation when the number is small
    # enough that converting it to float cannot overflow, otherwise a power of
    # two from the bit length. The float value is inexact, so either way the
    # result is corrected with integer arithmetic only.
    if n < (1 << 104):
        r = int(n ** 0.5)
    else:
        r = 1 << ((n.bit_length() + 1) // 2 - 1)
    # Walk to the floor of the true square root. (Only relevant for n that are
    # actual perfect squares, which always satisfy result**2 == n.)
    while r * r > n:
        r -= 1
    while (r + 1) * (r + 1) <= n:
        r += 1
    return r

def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if n == 0:
        return 0
    # Seed the correction loop. The float path only runs for numbers small
    # enough that both converting n to a float and converting the float
    # square root back to an int succeed; above that boundary, 2**104 - 1 is
    # the first n whose float square root rounds up to a full 2**1024.
    if n < (1 << 103):
        r = int(n ** 0.5)
    else:
        r = 1 << ((n.bit_length() + 1) // 2 - 1)
    # Walk to the floor of the true square root. For perfect squares this
    # converges in at most a few steps; for non-perfect squares it lands on
    # the integer floor, the standard definition of an integer square root.
    while r * r > n:
        r -= 1
    while (r + 1) * (r + 1) <= n:
        r += 1
    return r
